const person = {

  firstName: "John",

  lastName: "Doe",

  fullName: function() {

    return this.firstName + " " + this.lastName;

  }

};

person.fullName();

function myFunction() {

    return this;

}

"use strict";

function myFunction() {

  return this;

}

// Regular Function:
hello = function() {
  document.getElementById("demo").innerHTML
  += this;
}

// The window object calls the function:

  window.addEventListener("load", hello);

// A button object calls the
  function:
document.getElementById("btn").addEventListener("click", hello);

// Arrow Function:
hello = () => {
  document.getElementById("demo").innerHTML
  += this;
}

// The window object calls the function:

  window.addEventListener("load", hello);

// A button object calls the
  function:
document.getElementById("btn").addEventListener("click", hello);

const person = {

      firstName: "John",

      sayHello: () => {

        return this.firstName;

      }

    };

    person.sayHello();

const person = {

      firstName: "John",

      sayHello: function() {

        return () => this.firstName;

      }

    };

    let hello = person.sayHello();

    hello();
